// подмножества циклом; с повторами во входе — после Array.Sort(nums)
void Dfs(int start) {
    res.Add(new List<int>(path));                    // каждый узел — ответ
    for (int i = start; i < nums.Length; i++) {
        if (i > start && nums[i] == nums[i - 1]) continue;  // повтор на уровне
        path.Add(nums[i]);
        Dfs(i + 1);                                  // дальше — только правее i
        path.RemoveAt(path.Count - 1);
    }
}
